export function getAllBlogPosts(): BlogPost[] {
  return blogPosts;
}

export function getBlogBySlug(slug: string): BlogPost | undefined {
  return blogPosts.find((b) => b.slug === slug);
}

export function getFeaturedBlogPost(): BlogPost | undefined {
  return blogPosts.find((b) => b.featured);
}

export function getLatestBlogPosts(limit: number): BlogPost[] {
  return [...blogPosts]
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())
    .slice(0, limit);
}

export function getRelatedBlogPosts(slug: string, limit: number): BlogPost[] {
  const current = getBlogBySlug(slug);
  if (!current) return [];
  return blogPosts
    .filter((b) => b.slug !== slug && b.category === current.category)
    .slice(0, limit);
}

export function getBlogPostsByCategory(category: string): BlogPost[] {
  return blogPosts.filter((b) => b.category === category);
}

